function createLocalSupabase(enableMockAuth = import.meta.env.DEV): SupabaseClient<Database> {
  const loadTables = (): Record<string, any[]> => {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        const seed = getInitialSeed();
        const merged = { ...seed, ...parsed };

        // Ensure testimonials exist in merged store even if user had older localStorage
        if (!Array.isArray(merged.testimonials) || merged.testimonials.length === 0) {
          merged.testimonials = seed.testimonials;
          try {
            localStorage.setItem(STORAGE_KEY, JSON.stringify(merged));
          } catch {
            // ignore
          }
        }

        // Migrate any old 2026 seed project dates in localStorage back to 2024 so user-created projects always sort first
        if (Array.isArray(merged.projects)) {
          let mutated = false;
          merged.projects = merged.projects.map((proj: any) => {
            const fixedSeedDate = SEED_PROJECT_DATES[proj.id];
            if (fixedSeedDate && String(proj.data_publicacao || '').startsWith('2026-')) {
              mutated = true;
              return {
                ...proj,
                data_publicacao: fixedSeedDate,
                created_at: fixedSeedDate,
              };
            }
            return proj;
          });
          if (mutated) {
            try {
              localStorage.setItem(STORAGE_KEY, JSON.stringify(merged));
            } catch {
              // ignore
            }
          }
        }

        return merged;
      }
    } catch {
      // ignore storage errors
    }
    const seed = getInitialSeed();
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(seed));
    } catch {
      // ignore
    }
    return seed;
  };

  const saveTables = (tables: Record<string, any[]>) => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(tables));
      if (typeof window !== 'undefined') {
        window.dispatchEvent(new Event('portfolio-store-updated'));
      }
    } catch {
      // ignore quota errors
    }
  };

  let tables = loadTables();
  const storageUrls = new Map<string, string>();

  let currentSession: any = null;
  try {
    const savedSession = enableMockAuth ? localStorage.getItem(SESSION_KEY) : null;
    if (savedSession) currentSession = JSON.parse(savedSession);
  } catch {
    // ignore
  }

  const authListeners = new Set<(event: string, session: any) => void>();

  const buildQuery = (table: string) => {
    tables = loadTables();
    let rows = [...(tables[table] || [])];
    let pendingOp: 'select' | 'insert' | 'update' | 'upsert' | 'delete' = 'select';
    let payload: any = null;
    const filters: Array<(row: any) => boolean> = [];
    let sortCol: string | null = null;
    let sortAsc = true;
    let limitCount: number | null = null;
    let isSingle = false;
    let isMaybeSingle = false;

    const execute = async () => {
      tables = loadTables();
      const tableData = tables[table] || (tables[table] = []);

      if (!enableMockAuth && pendingOp !== 'select') {
        return {
          data: null,
          error: new Error('Supabase is not configured for this deployment.'),
        };
      }

      if (pendingOp === 'insert') {
        const items = Array.isArray(payload) ? payload : [payload];
        const inserted = items.map((item) => ({
          id: item.id || crypto.randomUUID(),
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
          ...item,
        }));
        tableData.unshift(...inserted);
        saveTables(tables);
        return { data: isSingle || isMaybeSingle ? inserted[0] ?? null : inserted, error: null };
      }

      if (pendingOp === 'upsert') {
        const items = Array.isArray(payload) ? payload : [payload];
        const upserted = items.map((item) => {
          const idx = tableData.findIndex((r) =>
            filters.length
              ? filters.every((f) => f(r))
              : (item.id && r.id === item.id) || (item.key && r.key === item.key) || (item.slug && r.slug === item.slug)
          );
          if (idx >= 0) {
            tableData[idx] = { ...tableData[idx], ...item, updated_at: new Date().toISOString() };
            return tableData[idx];
          }
          const created = {
            id: item.id || crypto.randomUUID(),
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString(),
            ...item,
          };
          tableData.push(created);
          return created;
        });
        saveTables(tables);
        return { data: upserted, error: null };
      }

      if (pendingOp === 'update') {
        const updated: any[] = [];
        tables[table] = tableData.map((r) => {
          if (filters.every((f) => f(r))) {
            const next = { ...r, ...payload, updated_at: new Date().toISOString() };
            updated.push(next);
            return next;
          }
          return r;
        });
        saveTables(tables);
        return { data: isSingle || isMaybeSingle ? updated[0] ?? null : updated, error: null };
      }

      if (pendingOp === 'delete') {
        tables[table] = tableData.filter((r) => !filters.every((f) => f(r)));
        saveTables(tables);
        return { data: null, error: null };
      }

      // SELECT
      rows = tableData.filter((r) => filters.every((f) => f(r)));
      if (sortCol) {
        const col = sortCol;
        rows.sort((a, b) => {
          const va = a[col] ?? '';
          const vb = b[col] ?? '';
          if (va < vb) return sortAsc ? -1 : 1;
          if (va > vb) return sortAsc ? 1 : -1;
          return 0;
        });
      }
      if (limitCount !== null) {
        rows = rows.slice(0, limitCount);
      }
      if (isSingle) {
        if (rows.length === 0) {
          return { data: null, error: { message: 'Row not found', code: 'PGRST116' } };
        }
        return { data: rows[0], error: null };
      }
      if (isMaybeSingle) {
        return { data: rows[0] ?? null, error: null };
      }
      return { data: rows, error: null };
    };

    const builder: any = {
      select: () => builder,
      insert: (data: any) => {
        pendingOp = 'insert';
        payload = data;
        return builder;
      },
      update: (data: any) => {
        pendingOp = 'update';
        payload = data;
        return builder;
      },
      upsert: (data: any) => {
        pendingOp = 'upsert';
        payload = data;
        return builder;
      },
      delete: () => {
        pendingOp = 'delete';
        return builder;
      },
      eq: (col: string, val: any) => {
        filters.push((r) => r[col] === val);
        return builder;
      },
      neq: (col: string, val: any) => {
        filters.push((r) => r[col] !== val);
        return builder;
      },
      in: (col: string, vals: any[]) => {
        filters.push((r) => Array.isArray(vals) && vals.includes(r[col]));
        return builder;
      },
      order: (col: string, opts?: { ascending?: boolean }) => {
        sortCol = col;
        sortAsc = opts?.ascending ?? true;
        return builder;
      },
      limit: (n: number) => {
        limitCount = n;
        return builder;
      },
      single: () => {
        isSingle = true;
        return builder;
      },
      maybeSingle: () => {
        isMaybeSingle = true;
        return builder;
      },
      then: (onfulfilled?: (value: any) => any, onrejected?: (reason: any) => any) =>
        execute().then(onfulfilled, onrejected),
    };

    return builder;
  };

  const fileToDataUrl = (file: File): Promise<string> =>
    new Promise((resolve) => {
      const reader = new FileReader();
      reader.onloadend = () => resolve(typeof reader.result === 'string' ? reader.result : URL.createObjectURL(file));
      reader.onerror = () => resolve(URL.createObjectURL(file));
      reader.readAsDataURL(file);
    });

  return {
    from: (table: string) => buildQuery(table),
    auth: {
      onAuthStateChange: (callback: (event: string, session: any) => void) => {
        authListeners.add(callback);
        setTimeout(() => callback('INITIAL_SESSION', currentSession), 0);
        return {
          data: {
            subscription: {
              unsubscribe: () => {
                authListeners.delete(callback);
              },
            },
          },
        };
      },
      getSession: async () => ({
        data: { session: currentSession },
        error: null,
      }),
      signInWithPassword: async ({ email }: { email: string; password?: string }) => {
        if (!enableMockAuth) {
          return {
            data: { user: null, session: null },
            error: new Error('Supabase is not configured for this deployment.'),
          };
        }

        const user = {
          id: 'mock-admin-id',
          email: email || 'admin@lucasevangelista.design',
          created_at: new Date().toISOString(),
        };
        currentSession = {
          access_token: 'mock-access-token',
          user,
        };
        try {
          localStorage.setItem(SESSION_KEY, JSON.stringify(currentSession));
        } catch {
          // ignore
        }
        // Ensure user_roles always has admin role for mock-admin-id
        tables = loadTables();
        if (!tables.user_roles?.some((r: any) => r.user_id === 'mock-admin-id' && r.role === 'admin')) {
          tables.user_roles = [{ id: 'role-admin', user_id: 'mock-admin-id', role: 'admin' }];
          saveTables(tables);
        }
        authListeners.forEach((cb) => cb('SIGNED_IN', currentSession));
        return { data: { user, session: currentSession }, error: null };
      },
      signOut: async () => {
        currentSession = null;
        try {
          localStorage.removeItem(SESSION_KEY);
        } catch {
          // ignore
        }
        authListeners.forEach((cb) => cb('SIGNED_OUT', null));
        return { error: null };
      },
    },
    storage: {
      from: () => ({
        upload: async (path: string, file: File) => {
          if (!enableMockAuth) {
            return {
              data: null,
              error: new Error('Supabase is not configured for this deployment.'),
            };
          }
          const dataUrl = await fileToDataUrl(file);
          storageUrls.set(path, dataUrl);
          return { data: { path }, error: null };
        },
        getPublicUrl: (path: string) => ({
          data: { publicUrl: storageUrls.get(path) || path },
        }),
      }),
    },
  } as unknown as SupabaseClient<Database>;
}

const supabaseUrl = import.meta.env.VITE_SUPABASE_URL;
const supabaseKey = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;

export const isSupabaseConfigured = Boolean(supabaseUrl && supabaseKey);

export const supabase: SupabaseClient<Database> = isSupabaseConfigured
  ? createClient<Database>(supabaseUrl!, supabaseKey!)
  : createLocalSupabase(import.meta.env.DEV);
